import { Scene, NumberPlane, ValueTracker, alwaysRedraw, Color } from "retiam";

const scene = new Scene({ canvas });

const plane = new NumberPlane();
scene.add(plane);

// 1. Reactive frequency tracker
const freq = new ValueTracker(1.0);

// 2. High-performance reactive curve redraw
const wave = alwaysRedraw(() => {
    return plane.plot((x) => Math.sin(x * freq.value), {
        stroke: Color.fromHex("#38bdf8"),
        stroke_width: 0.08
    });
});
scene.add(wave);

// 3. Smoothly animate frequency from 1 Hz to 4 Hz
await scene.play(freq.animateValue(4.0, { duration: 2500 }));
